import click
from click._utils import UNSET

class CustomClickContext(click.Context):
    def lookup_default(self, name: str, call: bool = False):
        if call:
            default = super().lookup_default(name, call=True)
        else:
            default = super().lookup_default(name, call=False)

        # Original logic (kept to reproduce): treats any non-None (including sentinel) as a real default.
        if default is not None:
            return default
        prefix = name.split("_", 1)[0]
        group = getattr(self, "default_map", {}).get(prefix)
        if group:
            return group.get(name)
        return default

def test_lookup_default_returns_none():
    default_map = {"app": {"email": "prefix-param-level@example.com"}}
    cmd = click.Command("get-views")
    ctx = CustomClickContext(cmd, info_name=None)
    ctx.default_map = default_map

    val = ctx.lookup_default("email", False)

    # In older versions, lookup_default returned None if not found, 
    # making `val` None here.
    # In 8.3.0+, it returns Sentinel.UNSET.
    assert val is None, f"Expected None, but got {type(val)}: {val}"

import click
import pytest

class Foo:
    pass

class Bar:
    pass

@click.command()
@click.option("--foo", "ty", flag_value=Foo, type=click.UNPROCESSED, default=True)
@click.option("--bar", "ty", flag_value=Bar, type=click.UNPROCESSED)
def main(ty):
    click.echo(repr(ty))

def test_flag_value_class_not_instantiated():
    from click.testing import CliRunner
    runner = CliRunner()
    result = runner.invoke(main, [])
    assert result.exit_code == 0
    # Expected output: "<class '__main__.Foo'>"
    # Actual output (reported): "<__main__.Foo object at ...>"
    assert result.output.strip() == "<class 'test_issue_repro_3121.Foo'>"

import click
import pytest
from typing import Any

# Mock semver Version since it's not installed
class MockVersion:
    def __init__(self, major, minor, patch):
        self.major = major
        self.minor = minor
        self.patch = patch

    def __eq__(self, other):
        if isinstance(other, str):
            # This is the behavior that causes the crash:
            # Trying to parse the string to compare
            # In real semver, it calls .parse(other)
            raise ValueError(f"{other} is not valid SemVer string")
        return isinstance(other, MockVersion) and \
               (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

    def __str__(self):
        return f"{self.major}.{self.minor}.{self.patch}"

class VersionType(click.ParamType):
    name = "version"
    def convert(self, value, param, ctx):
        return value

def test_custom_type_default_help_text():
    @click.command()
    @click.option(
        "--version",
        type=VersionType(),
        default=MockVersion(1, 0, 0),
        show_default=True,
    )
    def cli(version) -> None:
        pass

    # This should trigger the bug
    ctx = click.Context(cli)
    try:
        cli.get_help(ctx)
    except Exception as e:
        pytest.fail(f"get_help raised an exception: {e}")

import click
from click.testing import CliRunner

def test_nested_command_option_shadowing_help():
    @click.group(context_settings={"help_option_names": ["-h", "--help"]})
    def cli():
        pass

    @click.command()
    @click.argument("required_arg")
    @click.option("--host", "-h", "host", default="localhost")
    def foo(required_arg, host):
        click.echo(f"Foo command required_arg={required_arg} host={host}")

    cli.add_command(foo)

    runner = CliRunner()
    result = runner.invoke(cli, ["foo"])

    assert result.exit_code != 0
    # The reported issue says it currently says:
    # Try 'click-test-cli foo -h' for help.
    # But it should say:
    # Try 'click-test-cli foo --help' for help.

    assert "Try 'cli foo -h' for help." not in result.output
    assert "Try 'cli foo --help' for help." in result.output
